"use client";

import Link from "next/link";
import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  asArray, asObject, contactState, contextLabel, discoverySignal, dispositionReason, facts, formatDate, inferences, intelligence, lensLabel, latestRun, matchesRunResultMetric, needsReview,
  operatorActivityLabel, operatorContactState, operatorNextAction, operatorPersonLabel, operatorRoleLabel, operatorWorkflowState, operatorWhyRelevant, organisationName, paginationModel, primaryOpportunity, prospectPriority, prospectType, resolutionLabel, resultDataQualityWarnings, reviewDecision, reviewReason, runCounts, runResultReconciliation, shortId, siteTypeLabel, sourceType, statusLabel, territoryLabel, unknowns, contactShortLabel, type OperatorCandidate, type RunResultMetric,
  type OperatorOverview, type OperatorOverviewItem, type OperatorPayload, type OperatorRun, type OperatorRunHistoryRow,
} from "../../src/operator-ui/logic";
import { blockReasonLabel, PROSPECT_BLOCK_REASON_OPTIONS } from "../../src/operator-ui/prospect-review";

function useOperatorData(query: string) {
  const [data, setData] = useState<OperatorPayload & { selectedRun?: OperatorRun | null }>({ access: "VIEWER", runs: [], candidates: [], latestRunId: null });
  const [state, setState] = useState<"loading" | "ready" | "error">("loading");
  const refresh = useCallback(async () => { setState("loading"); try { const response = await fetch(`/api/operator?${query}`); if (!response.ok) throw new Error((await response.json()).message); setData(await response.json()); setState("ready"); } catch { setState("error"); } }, [query]);
  useEffect(() => { void refresh(); }, [refresh]);
  return { data, state, refresh };
}

function PageHeader({ eyebrow, title, lede, action, compact = false }: { eyebrow: string; title: string; lede: string; action?: React.ReactNode; compact?: boolean }) {
  return <header className={compact ? "operator-page-header compact" : "operator-page-header"}><div><span className="operator-kicker">{eyebrow}</span><h1>{title}</h1><p>{lede}</p></div>{action}</header>;
}

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) { return <span className={`operator-badge ${tone}`}>{children}</span>; }
function Loading({ label = "Loading operator data…" }: { label?: string }) { return <div className="operator-empty"><span className="operator-kicker">PLEASE WAIT</span><p>{label}</p></div>; }
function ErrorState() { return <div className="operator-empty error"><span className="operator-kicker">DATA UNAVAILABLE</span><h2>Operator data could not be loaded.</h2><p>Check that discovery persistence is available and try again.</p></div>; }
function EmptyState({ title, text }: { title: string; text: string }) { return <div className="operator-empty"><span className="operator-kicker">NO RESULTS</span><h2>{title}</h2><p>{text}</p></div>; }

function Stats({ run, candidates, onMetricFilter, activeMetric }: { run: OperatorRun | null; candidates: OperatorCandidate[]; onMetricFilter?: (metric: RunResultMetric) => void; activeMetric?: RunResultMetric }) {
  const counts = runCounts(run, candidates);
  const values: Array<{ key: RunResultMetric; label: string; value: number }> = [{ key: "found", label: "Found", value: counts.found }, { key: "resolved", label: "Resolved", value: counts.resolved }, { key: "unresolved", label: "Unresolved", value: counts.unresolved }, { key: "enriched", label: "Enriched", value: counts.enriched }, { key: "advanced", label: "Advanced", value: counts.advanced }, { key: "qualified", label: "Qualified", value: counts.qualified }, { key: "review", label: "Review", value: counts.review }, { key: "rejected", label: "Rejected", value: counts.rejected }, { key: "contactable", label: "Contactable", value: counts.contactable }];
  return <div className="operator-stats">{values.map(({ key, label, value }) => onMetricFilter ? <button className={activeMetric === key ? "operator-stat is-active" : "operator-stat"} type="button" key={key} aria-pressed={activeMetric === key} onClick={() => onMetricFilter(key)}><span>{label}</span><strong>{value}</strong></button> : <div className="operator-stat" key={key}><span>{label}</span><strong>{value}</strong></div>)}</div>;
}

function RunMeta({ run, compact = false }: { run: OperatorRun; compact?: boolean }) {
  const summary = asObject(run.summary);
  return <div className={compact ? "run-meta compact" : "run-meta"}><div><span className="operator-label">TERRITORY</span><strong>{territoryLabel(run.territory_code)}</strong></div><div><span className="operator-label">LENS</span><strong>{lensLabel(run.focus)}</strong></div><div><span className="operator-label">STATUS</span><Badge tone={run.status.toLowerCase()}>{run.status}</Badge></div>{!compact ? <><div><span className="operator-label">STARTED</span><strong>{formatDate(run.started_at ?? run.created_at)}</strong></div><div><span className="operator-label">COMPLETED</span><strong>{formatDate(run.completed_at)}</strong></div><div><span className="operator-label">RUN ID</span><strong className="mono">{shortId(run.id)}</strong></div></> : null}<span className="sr-only">Summary fields available: {Object.keys(summary).join(", ")}</span></div>;
}

function ResearchBrief({ run }: { run: OperatorRun }) {
  const summary = asObject(run.summary);
  const metadata = asObject(summary.provenance ?? summary.metadata);
  const brief = String(metadata.researchBrief ?? summary.researchBrief ?? summary.brief ?? "");
  return <section className="research-brief"><div><span className="operator-kicker">RESEARCH BRIEF</span><h2>{brief || "Research instruction not recorded for this run"}</h2><p>{brief ? "Plain-language instruction context for this run." : "Not recorded for this run. The interface does not infer private prompts or hidden model instructions."}</p></div><dl className="provenance-list"><div><dt>TRIGGER / SOURCE</dt><dd>{String(metadata.trigger ?? metadata.source ?? "Not recorded for this run")}</dd></div><div><dt>DISCOVERY PATH</dt><dd>{String(metadata.discoveryPath ?? "Not recorded for this run")}</dd></div><div><dt>RESEARCH LIMIT</dt><dd>{String(metadata.maxCandidates ?? asObject(run.budget).maxCandidates ?? "Not recorded for this run")}</dd></div><div><dt>APPLICATION VERSION</dt><dd>{String(metadata.applicationVersion ?? metadata.commitSha ?? metadata.deploymentVersion ?? "Not recorded for this run")}</dd></div></dl></section>;
}

function CollectionTable({ label, count, children, className = "" }: { label: string; count: number; children: React.ReactNode; className?: string }) {
  return <div className={`collection-table-wrap ${className} ${label === "Prospects" ? "prospect-queue-table" : ""}`}><table className="collection-table"><caption className="sr-only">{label}</caption>{children}</table><div className="collection-count">{count} records in this view</div></div>;
}

function OverviewMetric({ label, value, detail, href }: { label: string; value: number; detail: string; href: string }) {
  return <Link className="overview-metric" href={href}><span>{label}</span><strong>{value}</strong><small>{detail}</small></Link>;
}

function OverviewItem({ item }: { item: OperatorOverviewItem }) {
  return <Link className="overview-item" href={item.href}><span className="overview-item-marker" /><span><strong>{item.title}</strong><small>{item.detail}</small></span><span className="overview-item-arrow">↗</span></Link>;
}

function OverviewHealth({ overview }: { overview: OperatorOverview }) {
  const { inbound, prospects, research } = overview;
  return <section className="overview-health"><div className="section-heading"><span className="operator-kicker">WORKSPACE HEALTH</span><span className="muted">Live persisted counts</span></div><div className="overview-health-list"><Link href="/operator/incoming-leads"><span>Inbound</span><strong>{inbound.needsReview} need review</strong><small>{inbound.highIntent} high intent · {inbound.activeGenuine} active genuine</small></Link><Link href="/operator/prospects"><span>Prospects</span><strong>{prospects.canonical} canonical</strong><small>{prospects.identityDecisions} identity decisions · {prospects.contactable} contactable</small></Link><Link href="/operator/runs"><span>Research</span><strong>{research.totalRuns} runs</strong><small>{research.failedToday} failed today · {research.activeOrPartialRuns} active or partial</small></Link></div><p className="overview-data-note">Inbound activities and outbound research appearances are separate data domains. The dashboard does not count a research appearance as an incoming lead.</p></section>;
}

function formatRunDuration(seconds?: number | null) {
  if (seconds === null || seconds === undefined || !Number.isFinite(seconds)) return "Duration not recorded";
  const minutes = Math.floor(seconds / 60); const remainder = Math.max(0, seconds % 60);
  return `${String(minutes).padStart(2, "0")}:${String(remainder).padStart(2, "0")}`;
}

function SortButton({ label, active, direction, onClick }: { label: string; active: boolean; direction: "asc" | "desc"; onClick: () => void }) {
  return <button className={active ? "table-sort active" : "table-sort"} type="button" onClick={onClick}>{label}{active ? <span aria-hidden="true"> {direction === "asc" ? "↑" : "↓"}</span> : null}</button>;
}

function Pagination({ page, pageSize, total, pageCount, hasNext, hasPrevious, onNext, onPrevious, onPage, onPageSize }: { page: number; pageSize: number; total: number; pageCount?: number; hasNext?: boolean; hasPrevious?: boolean; onNext?: () => void; onPrevious?: () => void; onPage?: (page: number) => void; onPageSize: (size: number) => void }) {
  const pagination = paginationModel(total, page, pageSize);
  const safePageCount = Math.max(1, pageCount ?? pagination.pageCount);
  return <div className="pagination"><span>{pagination.rangeLabel}</span><label>Rows <select value={pageSize} onChange={(event) => { onPageSize(Number(event.target.value)); onPage?.(1); }}><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label><button type="button" disabled={hasPrevious === undefined ? pagination.page <= 1 : !hasPrevious} onClick={onPrevious ?? (() => onPage?.(pagination.page - 1))}>Previous</button><span>Page {Math.min(safePageCount, pagination.page)} of {safePageCount}</span><button type="button" disabled={hasNext === undefined ? pagination.page >= safePageCount : !hasNext} onClick={onNext ?? (() => onPage?.(pagination.page + 1))}>Next</button></div>;
}

function CandidateLink({ candidate }: { candidate: OperatorCandidate }) { return <Link className="table-action" href={`/operator/prospects/${candidate.id}`}>Open ↗</Link>; }

function CandidateRow({ candidate, latestRunId, onSelect, selected = false, review = false, showAttention = true }: { candidate: OperatorCandidate; latestRunId: string | null; onSelect?: () => void; selected?: boolean; review?: boolean; showAttention?: boolean }) {
  const unresolved = organisationName(candidate) === "ORGANISATION NOT YET RESOLVED";
  return <tr className={selected ? "is-selected" : undefined} tabIndex={onSelect ? 0 : undefined} aria-selected={onSelect ? selected : undefined} onClick={onSelect} onKeyDown={(event) => { if (onSelect && (event.key === "Enter" || event.key === " ")) { event.preventDefault(); onSelect(); } }}>
    {review ? <><td className="decision-cell"><strong>{reviewReason(candidate)}</strong><span>Specific decision required</span></td><td><strong className={unresolved ? "unresolved" : undefined}>{organisationName(candidate)}</strong><span>{territoryLabel(candidate.territory_code)}</span></td><td><strong>{discoverySignal(candidate)}</strong><span>{candidate.origin.replaceAll("_", " ")}</span></td><td><span>{reviewReason(candidate)}</span></td><td><span>{primaryOpportunity(candidate)}</span></td><td><span>{contactShortLabel(candidate)}</span></td><td><span>{formatDate(candidate.created_at, "Not recorded")}</span><small>{contextLabel(candidate, latestRunId)}</small></td><td><span>{shortId(candidate.discovery_run_id)}</span></td></> : <><td><strong className={unresolved ? "unresolved" : undefined}>{organisationName(candidate)}</strong><span>{territoryLabel(candidate.territory_code)}</span></td><td><strong>{discoverySignal(candidate)}</strong><span>{candidate.origin.replaceAll("_", " ")}</span></td><td><span>{siteTypeLabel(sourceType(candidate))}</span></td><td><Badge tone={resolutionLabel(candidate).toLowerCase().includes("resolved") ? "verified" : "review_required"}>{resolutionLabel(candidate)}</Badge></td><td><span>{primaryOpportunity(candidate)}</span></td><td><span>{contactShortLabel(candidate)}</span></td><td><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></td>{showAttention ? <td>{needsReview(candidate) ? <Badge tone="review_required">Needs decision</Badge> : <span>—</span>}</td> : null}<td><span>{formatDate(candidate.created_at, "Not recorded")}</span><small>{contextLabel(candidate, latestRunId)} · {shortId(candidate.discovery_run_id)}</small></td></>}
    <td><CandidateLink candidate={candidate} /></td>
  </tr>;
}

function CandidateInspector({ candidate, latestRunId, onClose }: { candidate: OperatorCandidate; latestRunId: string | null; onClose: () => void }) {
  const value = intelligence(candidate); const resolution = asObject(value.organisationResolution); const target = organisationName(candidate); const unknown = unknowns(candidate)[0] ?? "No important unknown recorded.";
  return <aside className="quick-inspector" aria-label="Quick prospect inspector"><div className="inspector-heading"><div><span className="operator-kicker">QUICK INSPECTOR</span><h2>{target}</h2></div><button className="inspector-close" type="button" onClick={onClose} aria-label="Close inspector">×</button></div><section><span className="operator-label">WHO WE THINK THE CUSTOMER IS</span><strong>{target}</strong><p>{resolution.officialWebsite ?? candidate.account?.website ?? "Authoritative site not recorded"}</p><p>Resolution: {resolutionLabel(candidate)}</p></section><section><span className="operator-label">WHAT WE FOUND</span><strong>{discoverySignal(candidate)}</strong><p>{siteTypeLabel(sourceType(candidate))} · {territoryLabel(candidate.territory_code)}</p></section><section><span className="operator-label">WHY IT MATTERS</span><strong>{primaryOpportunity(candidate)}</strong><p>{String(asArray<any>(value.commercialEvidence ?? value.evidence)[0]?.claim ?? value.eventConnection?.reasons?.[0] ?? "Commercial evidence not recorded")}</p><p className="inspector-unknown">Unknown / blocker: {unknown}</p></section><section><span className="operator-label">CONTACT</span><strong>{contactShortLabel(candidate)}</strong><p>{candidate.contacts?.length ? "Persisted public ownership evidence is available." : "No verified ownership evidence is shown."}</p></section><section><span className="operator-label">DECISION / NEXT ACTION</span><strong>{reviewDecision(candidate) || String(value.recommendedNextAction ?? "No specific human decision required")}</strong><p>{contextLabel(candidate, latestRunId)} · {statusLabel(candidate.status)}</p></section><Link className="operator-button" href={`/operator/prospects/${candidate.id}`}>Open full prospect ↗</Link></aside>;
}

function CandidateCard({ candidate, latestRunId }: { candidate: OperatorCandidate; latestRunId: string | null }) {
  return <Link href={`/operator/prospects/${candidate.id}`} className="candidate-card"><div className="candidate-card-top"><Badge tone={contextLabel(candidate, latestRunId).toLowerCase()}>{contextLabel(candidate, latestRunId)}</Badge><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></div><h3>{organisationName(candidate)}</h3><p>{discoverySignal(candidate)} <span>·</span> {territoryLabel(candidate.territory_code)}</p><div className="candidate-facts"><span>{primaryOpportunity(candidate)}</span><span>{contactShortLabel(candidate)}</span><span>{siteTypeLabel(sourceType(candidate))}</span></div><div className="found-run"><span className="operator-label">FOUND IN RUN</span><strong>{formatDate(candidate.created_at)} · {shortId(candidate.discovery_run_id)}</strong></div></Link>;
}

function RunResultsWorkspace({ run, candidates, latestRunId, showAttention = true }: { run: OperatorRun; candidates: OperatorCandidate[]; latestRunId: string | null; showAttention?: boolean }) {
  const [metric, setMetric] = useState<RunResultMetric>("found");
  const [query, setQuery] = useState("");
  const [disposition, setDisposition] = useState("ALL");
  const [lane, setLane] = useState("ALL");
  const scoped = useMemo(() => candidates.filter((candidate) => candidate.discovery_run_id === run.id), [candidates, run.id]);
  const attention = scoped.filter(needsReview);
  const reconciliation = runResultReconciliation(run, scoped);
  const visible = useMemo(() => {
    const text = query.trim().toLowerCase();
    return scoped.filter((candidate) => {
      const searchable = [organisationName(candidate), candidate.candidate_name, candidate.website, candidate.origin, candidate.status, dispositionReason(candidate), ...facts(candidate).map((fact) => fact.claim), ...asArray<string>(candidate.source_urls)].filter(Boolean).join(" ").toLowerCase();
      return matchesRunResultMetric(candidate, metric) && (disposition === "ALL" || candidate.status === disposition) && (lane === "ALL" || candidate.origin === lane) && (!text || searchable.includes(text));
    });
  }, [disposition, lane, metric, query, scoped]);
  const filtered = metric !== "found" || disposition !== "ALL" || lane !== "ALL" || Boolean(query.trim());
  const noResultsTitle = reconciliation.missing > 0 && scoped.length === 0
    ? "Historical data incomplete"
    : scoped.length === 0
      ? "No prospects were found"
      : "No results match these filters";
  const noResultsText = reconciliation.missing > 0 && scoped.length === 0
    ? `${reconciliation.recordedFound} result${reconciliation.recordedFound === 1 ? " was" : "s were"} counted for this older run, but no recoverable result record was retained.`
    : scoped.length === 0
      ? "This completed run persisted no candidate results."
      : "Adjust or clear the result filters to inspect the persisted run ledger.";
  const selectMetric = (next: RunResultMetric) => { setMetric(next); setDisposition("ALL"); };
  return <>
    <Stats run={run} candidates={scoped} activeMetric={metric} onMetricFilter={selectMetric} />
    <p className="run-metric-note">Click a metric to filter persisted results. Qualified, review and rejected are current dispositions; resolution, enrichment and contactability are recorded milestones.</p>
    {reconciliation.missing > 0 ? <div className="historical-incomplete" role="status"><span className="operator-kicker">HISTORICAL DATA INCOMPLETE</span><strong>{reconciliation.recordedFound} found, {reconciliation.persisted} recoverable result record{reconciliation.persisted === 1 ? "" : "s"}.</strong><p>Older aggregate counters are retained, but missing result detail is not reconstructed from guesses.</p></div> : null}
    {showAttention ? <section className="attention-section"><div className="section-heading"><span className="operator-kicker">WHAT NEEDS YOUR ATTENTION?</span><span className="muted">{attention.length} decision-oriented items</span></div>{attention.length ? <div className="attention-list">{attention.slice(0, 4).map((candidate) => <CandidateCard candidate={candidate} latestRunId={latestRunId} key={candidate.id} />)}</div> : <EmptyState title="No human decisions are required" text="All persisted results remain available below; the team is not manufacturing a review task." />}</section> : null}
    <section className="candidate-section"><div className="section-heading"><span className="operator-kicker">ALL RUN RESULTS</span><span className="muted">{scoped.length} persisted result{scoped.length === 1 ? "" : "s"}</span></div><div className="filter-panel run-result-filters"><label>Search<input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Organisation, event, reason or source" /></label><label>Disposition<select value={disposition} onChange={(event) => setDisposition(event.target.value)}><option value="ALL">All dispositions</option><option value="QUALIFIED">Qualified</option><option value="REVIEW_REQUIRED">Needs review</option><option value="REJECTED">Rejected</option><option value="BLOCKED">Blocked</option><option value="DUPLICATE">Duplicate</option><option value="RESEARCHED">Researched</option><option value="RESOLVED">Resolved</option><option value="DISCOVERED">Discovered</option></select></label><label>Discovery lane<select value={lane} onChange={(event) => setLane(event.target.value)}><option value="ALL">All lanes</option><option value="EVENT_FIRST">Event</option><option value="ORGANISATION_FIRST">Organisation</option><option value="PERSON_FIRST">Person</option><option value="VENUE_FIRST">Venue</option></select></label>{filtered ? <button type="button" className="table-action" onClick={() => { setMetric("found"); setQuery(""); setDisposition("ALL"); setLane("ALL"); }}>Clear filters</button> : null}</div>{visible.length ? <CollectionTable label="All run results" count={visible.length} className="run-results-table"><thead><tr><th>IDENTITY</th><th>RESULT TYPE / LANE</th><th>RESOLUTION</th><th>DISPOSITION</th><th>REASON</th><th>EVIDENCE / SOURCE</th><th>DATA QUALITY</th><th>ACTION</th></tr></thead><tbody>{visible.map((candidate) => { const fact = facts(candidate)[0]; const source = fact?.sourceUrl ?? asArray<string>(candidate.source_urls)[0]; const warnings = resultDataQualityWarnings(candidate); return <tr key={candidate.id}><td><strong>{organisationName(candidate)}</strong><span>{discoverySignal(candidate)}</span></td><td><strong>{prospectType(candidate)}</strong><span>{candidate.origin.replaceAll("_", " ")}</span></td><td>{resolutionLabel(candidate)}</td><td><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></td><td>{dispositionReason(candidate)}</td><td>{source ? <a href={String(source)} target="_blank" rel="noreferrer">{fact?.sourceTitle ?? "Open source"} ↗</a> : <span>Source not recorded</span>}</td><td>{warnings.length ? warnings.join(" · ") : "No material warning recorded"}</td><td><CandidateLink candidate={candidate} /></td></tr>; })}</tbody></CollectionTable> : <EmptyState title={noResultsTitle} text={noResultsText} />}</section>
  </>;
}

export function OverviewView() {
  const { data, state } = useOperatorData("view=overview");
  if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const overview = data.overview;
  if (!overview) return <ErrorState />;
  const { inbound, prospects, research, highestValueAction } = overview;
  return <><PageHeader eyebrow="OPERATOR WORKSPACE" title="Decide what deserves attention." lede="A supervised command centre for inbound interest, prospect decisions and research health." action={<span className="overview-refresh">REFRESHED {formatDate(overview.refreshedAt)}</span>} /><section className="highest-value-action"><div><span className="operator-kicker">HIGHEST-VALUE NEXT ACTION</span><h2>{highestValueAction.title}</h2><p>{highestValueAction.detail}</p></div><Link className="operator-button" href={highestValueAction.href}>Open {highestValueAction.kind.startsWith("INBOUND") ? "Incoming Leads" : "Prospect Inventory"} ↗</Link></section><section className="overview-glance"><div className="section-heading"><span className="operator-kicker">TODAY AT A GLANCE</span><span className="muted">Inbound, decisions and execution</span></div><div className="overview-metrics"><OverviewMetric label="Inbound review" value={inbound.needsReview} detail={`${inbound.highIntent} high intent`} href="/operator/incoming-leads?view=needs-review" /><OverviewMetric label="Identity decisions" value={prospects.identityDecisions} detail="Prospect Inventory" href="/operator/prospects?queue=NEEDS_REVIEW" /><OverviewMetric label="Qualification" value={prospects.qualificationDecisions} detail="Ready after identity" href="/operator/prospects?queue=QUALIFIED" /><OverviewMetric label="Contact decisions" value={prospects.contactDecisions} detail={`${prospects.qualified} qualified · route needed`} href="/operator/prospects?queue=CONTACTABLE" /></div></section><div className="overview-lower-grid"><section className="overview-attention"><div className="section-heading"><span className="operator-kicker">ATTENTION QUEUE</span><span className="muted">{overview.attention.length} prioritized items</span></div>{overview.attention.length ? <div className="overview-item-list">{overview.attention.slice(0, 6).map((item) => <OverviewItem item={item} key={`${item.kind}-${item.id}`} />)}</div> : <EmptyState title="Nothing needs attention" text="The workspace has no persisted inbound, prospect or run decisions waiting for you." />}</section><OverviewHealth overview={overview} /></div><section className="overview-recent"><div className="section-heading"><span className="operator-kicker">RECENT CHANGES</span><span className="muted">Latest persisted activity</span></div><div className="overview-recent-list">{overview.recentChanges.map((item) => <OverviewItem item={item} key={`${item.kind}-${item.id}`} />)}</div></section><section className="overview-source-note"><span className="operator-kicker">LATEST RESEARCH CONTEXT</span><p>{research.latestRun?.found ?? 0} appearance in the latest bounded run · {research.latestRun?.status?.toLowerCase() ?? "no run"} · {research.stale ? "stale run warning" : "current run"}. Research context supports the command centre; it does not replace the inbound lead queue.</p><Link href={research.latestRun?.id ? `/operator/runs/${research.latestRun.id}` : "/operator/runs"}>Inspect research runs ↗</Link></section></>;
}

export function RunsView() {
  const { data, state } = useOperatorData("view=runs"); const [filter, setFilter] = useState("ALL");
  if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const history = data.runHistory && !Array.isArray(data.runHistory) ? data.runHistory : null; if (!history || !Array.isArray(history.runs) || !history.summary) return <ErrorState />;
  const latest = history.runs[0]?.id;
  const runs = history.runs.filter((run) => filter === "ALL" || (filter === "LATEST" ? run.id === latest : filter === "FAILED" ? ["FAILED", "ERROR"].includes(run.status.toUpperCase()) : filter === "REVIEW" ? run.currentDispositions.review > 0 : filter === "QUALIFIED" ? run.currentDispositions.qualified > 0 : true));
  const summary = history.summary;
  return <><PageHeader eyebrow="RESEARCH RUNS" title="Research runs" lede="Execution history stays separate from canonical prospects: inspect what each bounded run requested, found and introduced." /><div className="run-summary-cards"><div><span>Total runs</span><strong>{summary.totalRuns}</strong></div><div><span>Completed</span><strong>{summary.completedRuns}</strong></div><div><span>Appearances</span><strong>{summary.appearances}</strong></div><div><span>Introductions</span><strong>{summary.introductions}</strong></div></div><div className="quick-filter-bar" role="toolbar" aria-label="Run quick filters">{[["ALL", "All runs"], ["LATEST", "Latest"], ["REVIEW", "Has review"], ["QUALIFIED", "Has qualified"], ["FAILED", "Failed"]].map(([value, label]) => <button key={value} type="button" className={filter === value ? "quick-filter active" : "quick-filter"} onClick={() => setFilter(value)}>{label}</button>)}</div>{runs.length ? <CollectionTable label="Research runs" count={runs.length} className="run-history-table"><thead><tr><th>STARTED / SCOPE</th><th>EXECUTION FACTS</th><th>INTRODUCTIONS</th><th>CURRENT DISPOSITIONS</th><th>ACTION</th></tr></thead><tbody>{runs.map((run: OperatorRunHistoryRow) => <tr key={run.id}><td><strong>{run.id === latest ? <Badge tone="current">LATEST</Badge> : null}</strong><span>{formatDate(run.startedAt ?? run.createdAt)}</span><small>{territoryLabel(run.territoryCode)} · {lensLabel(run.focus)}</small></td><td><Badge tone={run.status.toLowerCase()}>{run.status}</Badge><span>Requested {run.requested ?? "not recorded"} · {run.appearances} appearance{run.appearances === 1 ? "" : "s"}</span><small>{formatRunDuration(run.durationSeconds)} · {run.cost ?? "Cost not recorded"}</small></td><td><strong>{run.introductions} new</strong><span>{run.appearances} total appearances</span></td><td><strong>Review {run.currentDispositions.review}</strong><span>Qualified {run.currentDispositions.qualified} · Rejected {run.currentDispositions.rejected}</span></td><td><Link className="table-action" href={`/operator/runs/${run.id}`}>Inspect ↗</Link></td></tr>)}</tbody></CollectionTable> : <EmptyState title="No runs match this filter" text="Try a wider run scope. No records were changed." />}</>;
}

export function RunDetailView({ runId }: { runId: string }) {
  const { data, state } = useOperatorData(`view=run&runId=${encodeURIComponent(runId)}`); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const run = data.selectedRun ?? data.runs.find((item) => item.id === runId) ?? null; const candidates = data.candidates;
  if (!run) return <EmptyState title="Run not found" text="This run may not be available to the current member." />;
  return <><PageHeader eyebrow="RUN DETAIL" title={`${territoryLabel(run.territory_code)} · ${lensLabel(run.focus)}`} lede="The run summary, provenance, decisions and complete persisted result ledger stay clearly separated." action={<Link className="operator-button secondary" href="/operator/runs">Back to runs</Link>} /><div className="detail-banner"><RunMeta run={run} /><ResearchBrief run={run} /></div><RunResultsWorkspace run={run} candidates={candidates} latestRunId={data.latestRunId} /><details className="diagnostics"><summary>Diagnostics (collapsed)</summary><div className="provenance-list"><div><span className="operator-label">RUN ID</span><strong className="mono">{run.id}</strong></div><div><span className="operator-label">PROVIDER / MODEL</span><strong>{run.provider ?? "Not recorded"} · {run.model ?? "Not recorded"}</strong></div><div><span className="operator-label">TECHNICAL OUTCOME</span><strong>{run.status}</strong></div><div><span className="operator-label">ERROR CONTEXT</span><strong>{run.error_message ?? "None recorded"}</strong></div></div><p className="muted">Private prompts, secrets, API keys and hidden reasoning are never rendered.</p></details></>;
}

export function LegacyProspectsView() {
  const { data, state } = useOperatorData("view=prospects"); const [query, setQuery] = useState(""); const [scope, setScope] = useState("ACTIVE"); const [territory, setTerritory] = useState("ALL"); const [source, setSource] = useState("ALL"); const [resolution, setResolution] = useState("ALL"); const [opportunity, setOpportunity] = useState("ALL"); const [status, setStatus] = useState("ALL"); const [contact, setContact] = useState("ALL"); const [sort, setSort] = useState<"attention" | "organisation" | "found" | "status">("attention"); const [direction, setDirection] = useState<"asc" | "desc">("desc"); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(50); const [selectedId, setSelectedId] = useState<string | null>(null);
  const latest = data.latestRunId; const filtered = useMemo(() => { const text = query.toLowerCase(); return data.candidates.filter((candidate) => { const intelligenceValue = intelligence(candidate); const searchable = `${organisationName(candidate)} ${candidate.candidate_name} ${candidate.website ?? ""} ${sourceType(candidate)}`.toLowerCase(); const context = contextLabel(candidate, latest); const candidateResolution = resolutionLabel(candidate); const candidateOpportunity = primaryOpportunity(candidate); return (!text || searchable.includes(text)) && (scope === "ALL" || (scope === "ACTIVE" ? ["NEW", "CURRENT"].includes(context) && !["REJECTED", "DUPLICATE"].includes(candidate.status) : scope === "REVIEW" ? needsReview(candidate) : scope === "QUALIFIED" ? candidate.status === "QUALIFIED" : scope === "UNRESOLVED" ? candidateResolution === "Unresolved" : scope === "NO_CONTACT" ? contactShortLabel(candidate) === "No verified target contact" : scope === "PROVIDER" ? sourceType(candidate) === "TICKETING_PROVIDER" : ["HISTORICAL", "CALIBRATION", "LEGACY"].includes(context))) && (territory === "ALL" || candidate.territory_code === territory) && (source === "ALL" || sourceType(candidate) === source) && (resolution === "ALL" || (resolution === "RESOLVED" ? candidateResolution.startsWith("Resolved") : candidateResolution === "Unresolved")) && (opportunity === "ALL" || candidateOpportunity.toUpperCase().includes(opportunity)) && (status === "ALL" || candidate.status === status) && (contact === "ALL" || (contact === "VERIFIED" ? contactShortLabel(candidate) === "Verified target contact" : contactShortLabel(candidate) !== "Verified target contact")); }); }, [contact, data.candidates, latest, opportunity, query, resolution, scope, source, status, territory]);
  const sorted = useMemo(() => [...filtered].sort((a, b) => { const attention = (candidate: OperatorCandidate) => needsReview(candidate) ? 2 : candidate.status === "QUALIFIED" ? 1 : 0; const av = sort === "organisation" ? organisationName(a) : sort === "status" ? a.status : sort === "found" ? new Date(a.created_at ?? 0).getTime() : attention(a); const bv = sort === "organisation" ? organisationName(b) : sort === "status" ? b.status : sort === "found" ? new Date(b.created_at ?? 0).getTime() : attention(b); return (av < bv ? -1 : av > bv ? 1 : 0) * (direction === "asc" ? 1 : -1); }), [direction, filtered, sort]);
  if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const visible = sorted.slice((page - 1) * pageSize, page * pageSize); const selected = data.candidates.find((candidate) => candidate.id === selectedId) ?? null; const changeSort = (next: typeof sort) => { if (sort === next) setDirection(direction === "asc" ? "desc" : "asc"); else { setSort(next); setDirection(next === "found" ? "desc" : "asc"); } setPage(1); }; const clearFilters = () => { setQuery(""); setScope("ACTIVE"); setTerritory("ALL"); setSource("ALL"); setResolution("ALL"); setOpportunity("ALL"); setStatus("ALL"); setContact("ALL"); setPage(1); };
  return <><PageHeader eyebrow="PROSPECTS" title="Commercial targets, not CRM records" lede="Scan, compare and inspect the collection without turning provider or listing pages into prospect identity." /><div className="quick-filter-bar" role="toolbar" aria-label="Prospect quick filters">{[["ACTIVE", "Latest run"], ["REVIEW", "Needs review"], ["QUALIFIED", "Qualified"], ["UNRESOLVED", "Unresolved"], ["NO_CONTACT", "No verified contact"], ["PROVIDER", "Ticketing-provider source"], ["ALL", "Historical / all"]].map(([value, label]) => <button key={value} type="button" className={scope === value ? "quick-filter active" : "quick-filter"} onClick={() => { setScope(value); setPage(1); }}>{label}</button>)}<button type="button" className="quick-filter clear" onClick={clearFilters}>Clear filters</button></div><div className="filter-panel"><label>Search<input value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} placeholder="Organisation, event or source" /></label><label>Territory<select value={territory} onChange={(event) => { setTerritory(event.target.value); setPage(1); }}><option value="ALL">All territories</option><option value="ZA">South Africa</option><option value="GB">United Kingdom</option></select></label><label>Source type<select value={source} onChange={(event) => { setSource(event.target.value); setPage(1); }}><option value="ALL">All sources</option>{Object.keys(siteTypeLabelsForFilter).map((key) => <option key={key} value={key}>{siteTypeLabel(key)}</option>)}</select></label><label>Resolution<select value={resolution} onChange={(event) => { setResolution(event.target.value); setPage(1); }}><option value="ALL">All resolution</option><option value="RESOLVED">Resolved</option><option value="UNRESOLVED">Unresolved</option></select></label><label>Opportunity<select value={opportunity} onChange={(event) => { setOpportunity(event.target.value); setPage(1); }}><option value="ALL">All opportunities</option><option value="EVENT GROWTH">Event Growth</option><option value="TICKETING">Ticketing</option><option value="EVENT OPERATIONS">Event Operations</option></select></label><label>Status<select value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="ALL">All statuses</option>{Object.keys(statusLabelsForFilter).map((key) => <option key={key} value={key}>{statusLabel(key)}</option>)}</select></label><label>Contact<select value={contact} onChange={(event) => { setContact(event.target.value); setPage(1); }}><option value="ALL">All contactability</option><option value="VERIFIED">Verified target contact</option><option value="NONE">No verified target contact</option></select></label></div><div className="collection-toolbar"><span><strong>{filtered.length}</strong> matching records · page before filter is {data.candidates.length}</span><label>Sort <select value={sort} onChange={(event) => changeSort(event.target.value as typeof sort)}><option value="attention">Attention then recency</option><option value="found">Found date</option><option value="organisation">Organisation</option><option value="status">Status</option></select></label></div>{visible.length ? <div className={selected ? "collection-with-inspector has-inspector" : "collection-with-inspector"}><CollectionTable label="Prospects" count={filtered.length}><thead><tr><th><SortButton label="ORGANISATION" active={sort === "organisation"} direction={direction} onClick={() => changeSort("organisation")} /></th><th>DISCOVERY SIGNAL</th><th>SOURCE</th><th>RESOLUTION</th><th>OPPORTUNITY</th><th>CONTACT</th><th>STATUS</th><th>ATTENTION</th><th><SortButton label="FOUND" active={sort === "found"} direction={direction} onClick={() => changeSort("found")} /></th><th>ACTION</th></tr></thead><tbody>{visible.map((candidate) => <CandidateRow key={candidate.id} candidate={candidate} latestRunId={latest} selected={candidate.id === selectedId} onSelect={() => setSelectedId(candidate.id)} showAttention />)}</tbody></CollectionTable>{selected ? <CandidateInspector candidate={selected} latestRunId={latest} onClose={() => setSelectedId(null)} /> : null}</div> : <EmptyState title="No prospects match these filters" text="Try a wider scope or clear the active filters. No records were changed." />}<Pagination page={page} pageSize={pageSize} total={sorted.length} onPage={setPage} onPageSize={setPageSize} /></>;
}

const ProspectQueueRow = memo(function ProspectQueueRow({ candidate, selected, onOpen }: { candidate: OperatorCandidate; selected: boolean; onOpen: (id: string, trigger: HTMLElement) => void }) {
  const secondary = String(asObject(candidate.account?.metadata).eventName ?? candidate.candidate_name ?? "Activity not recorded");
  const status = operatorWorkflowState(candidate);
  return <tr className={selected ? "is-selected" : undefined} tabIndex={0} aria-selected={selected} onClick={(event) => onOpen(candidate.id, event.currentTarget)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); onOpen(candidate.id, event.currentTarget); } }}>
    <td><strong>{organisationName(candidate)}</strong><span>{secondary}</span><small>{territoryLabel(candidate.territory_code)}</small></td>
    <td>{prospectType(candidate)}</td>
    <td><span className="queue-why">{operatorWhyRelevant(candidate)}</span></td>
    <td>{operatorPersonLabel(candidate)}</td>
    <td><Badge tone={status.toLowerCase().replaceAll(" ", "_")}>{status}</Badge></td>
    <td><button type="button" className="queue-action" onClick={(event) => { event.stopPropagation(); onOpen(candidate.id, event.currentTarget); }}>{operatorNextAction(candidate)}</button></td>
  </tr>;
});

function ProspectDrawer({ candidate, loading = false, onClose, restoreFocus, onReviewSaved, reviewNotice, allowReopen }: { candidate: OperatorCandidate; loading?: boolean; onClose: () => void; restoreFocus: HTMLElement | null; onReviewSaved: (message: string) => Promise<void>; reviewNotice?: string; allowReopen: boolean }) {
  const closeRef = useRef<HTMLButtonElement | null>(null);
  const [tab, setTab] = useState<"Overview" | "People" | "Email" | "History">("Overview");
  const [composerMessage, setComposerMessage] = useState("Draft-only Composer actions remain supervised and never send.");
  const [reviewMode, setReviewMode] = useState<"BLOCK" | "REOPEN" | null>(null);
  const [reasonCode, setReasonCode] = useState("");
  const [otherExplanation, setOtherExplanation] = useState("");
  const [reviewNote, setReviewNote] = useState("");
  const [reviewMessage, setReviewMessage] = useState("");
  const [reviewBusy, setReviewBusy] = useState(false);
  const [composerDrafts, setComposerDrafts] = useState<any[]>([]);
  const [emailLoaded, setEmailLoaded] = useState(false);
  const [emailLoading, setEmailLoading] = useState(false);
  const [emailBusyKeys, setEmailBusyKeys] = useState<Set<string>>(new Set());
  const [editingVersionId, setEditingVersionId] = useState<string | null>(null);
  const [editSubject, setEditSubject] = useState("");
  const [editBody, setEditBody] = useState("");
  const value = intelligence(candidate);
  const resolution = asObject(value.organisationResolution);
  const fit = [value.egs, value.ticketing, value.ecc].map((item: unknown) => asObject(item)).filter((item) => item.opportunityStrength || item.rationale);
  const contacts = candidate.contacts ?? [];
  const drafts = composerDrafts;
  const prospectApproved = candidate.prospect_approval?.decision === "APPROVED";
  const canPrepareDraft = Boolean(prospectApproved && candidate.status !== "BLOCKED" && candidate.account_id);
  useEffect(() => {
    if (tab !== "Email" || !prospectApproved || emailLoaded || emailLoading) return;
    setEmailLoading(true);
    void fetch(`/api/ai-sales/outreach-composer?candidateId=${encodeURIComponent(candidate.id)}`)
      .then(async (response) => { const payload = await response.json(); if (!response.ok) throw new Error(payload.message ?? "Email drafts are unavailable."); return payload; })
      .then((payload) => {
        const versions = asArray<any>(payload.versions);
        const reviews = asArray<any>(payload.reviews);
        const latestByStage = new Map<string, any>();
        for (const version of versions) {
          const key = String(version.sequence_stage ?? version.sequenceStage ?? ""); const current = latestByStage.get(key);
          if (!current || Number(version.revision_number ?? 0) >= Number(current.revision_number ?? 0)) latestByStage.set(key, version);
        }
        const persistedVersions = [...latestByStage.values()].map((version) => {
          const review = reviews.filter((item) => item.draft_version_id === version.id).sort((a, b) => String(b.created_at ?? "").localeCompare(String(a.created_at ?? "")))[0];
          return { ...version, versionId: version.id, draftId: version.draft_id, sequenceStage: version.sequence_stage, bodyPlainText: version.body_plain_text, approved: review?.action === "APPROVE", rejected: review?.action === "REJECT", reviewAction: review?.action };
        });
        setComposerDrafts(persistedVersions.length ? persistedVersions : (prospectApproved ? asArray<any>(asObject(asObject(candidate.account?.metadata).outreachComposer).drafts) : []));
        setEmailLoaded(true);
      })
      .catch((error) => { const fallback = prospectApproved ? asArray<any>(asObject(asObject(candidate.account?.metadata).outreachComposer).drafts) : []; if (fallback.length) setComposerDrafts(fallback); setComposerMessage(error instanceof Error ? error.message : "Email drafts are unavailable."); })
      .finally(() => setEmailLoading(false));
  }, [candidate.id, emailLoaded, emailLoading, prospectApproved, tab]);
  useEffect(() => {
    closeRef.current?.focus();
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); onClose(); return; }
      if (event.key !== "Tab") return;
      const focusable = Array.from(document.querySelectorAll<HTMLElement>('[data-prospect-drawer] button, [data-prospect-drawer] a, [data-prospect-drawer] input, [data-prospect-drawer] textarea, [data-prospect-drawer] select')).filter((item) => !item.hasAttribute("disabled"));
      if (!focusable.length) return;
      const first = focusable[0]; const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => { document.removeEventListener("keydown", onKeyDown); restoreFocus?.focus(); };
  }, [onClose, restoreFocus]);
  async function prepareDraft() {
    if (!candidate.account_id) { setComposerMessage("A resolved account is required before a draft can be prepared."); return; }
    setComposerMessage("Preparing a draft for human review…");
    try {
      const response = await fetch("/api/ai-sales/outreach-composer", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "prepare", candidateId: candidate.id, accountId: candidate.account_id, briefId: asObject(candidate.account?.metadata).aiSalesBriefId, contactId: contacts[0]?.id, sequenceStage: "EMAIL_1" }) });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.message ?? "Composer is unavailable.");
      if (Array.isArray(payload.generated)) setComposerDrafts(payload.generated.map((item: any, index: number) => ({ ...item.model, renderedBody: item.renderedBody, telemetry: item.telemetry, versionId: payload.versionIds?.[index] ?? payload.versionId, draftId: payload.draftId, recipientName: contacts[0]?.full_name ?? null, recipientRole: contacts[0]?.role_title ?? null, approved: false })));
      setComposerMessage("Draft prepared. Review each message separately in the Email tab.");
    } catch (error) { setComposerMessage(error instanceof Error ? error.message : "Composer is unavailable."); }
  }
  async function emailReview(draft: any, action: string, extra: Record<string, unknown> = {}) {
    const busyKey = String(draft.versionId ?? draft.sequenceStage ?? "unknown");
    if (emailBusyKeys.has(busyKey)) return;
    setEmailBusyKeys((current) => new Set(current).add(busyKey));
    try {
    if (!draft.versionId) {
      setComposerDrafts((current) => current.map((item) => item === draft ? { ...item, approved: action === "APPROVE", rejected: action === "REJECT", reviewAction: action } : item));
      setComposerMessage(action === "APPROVE" ? "Email approved." : action === "REJECT" ? "Not approved." : "Email review recorded.");
      return;
    }
    setComposerMessage("Saving email review…");
    const response = await fetch("/api/ai-sales/outreach-composer", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "review", candidateId: candidate.id, versionId: draft.versionId, sequenceStage: draft.sequenceStage, reviewAction: action, ...extra }) });
    const payload = await response.json();
    if (!response.ok) throw new Error(payload.message ?? "Email review could not be saved.");
    setComposerDrafts((current) => current.map((item) => item.versionId === draft.versionId ? { ...item, approved: action === "APPROVE", rejected: action === "REJECT", reviewAction: action } : item));
    setComposerMessage(action === "APPROVE" ? "Email approved." : action === "REJECT" ? "Not approved." : "Email review recorded.");
    } finally {
      setEmailBusyKeys((current) => { const next = new Set(current); next.delete(busyKey); return next; });
    }
  }
  function beginEdit(draft: any) { setEditingVersionId(draft.versionId ?? draft.sequenceStage); setEditSubject(String(draft.subject ?? "")); setEditBody(String(draft.bodyPlainText ?? draft.body_plain_text ?? "")); }
  async function saveEdit(draft: any) {
    try {
      await emailReview(draft, "EDIT", { editedSubject: editSubject, editedBody: editBody, reasonTags: ["MANUAL_REWRITE"] });
      setComposerDrafts((current) => current.map((item) => item === draft ? { ...item, subject: editSubject, bodyPlainText: editBody, approved: false, rejected: false, reviewAction: "EDIT" } : item));
      setEditingVersionId(null); setComposerMessage("Edited draft saved. It needs approval again.");
    } catch (error) { setComposerMessage(error instanceof Error ? error.message : "Email edit could not be saved."); }
  }
  async function regenerateDraft(draft: any) {
    const busyKey = String(draft.versionId ?? draft.sequenceStage ?? "unknown");
    if (emailBusyKeys.has(busyKey)) return;
    setEmailBusyKeys((current) => new Set(current).add(busyKey)); setComposerMessage("Regenerating this email for human review…");
    try {
      const response = await fetch("/api/ai-sales/outreach-composer", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "revise", candidateId: candidate.id, draftId: draft.draftId, versionId: draft.versionId, accountId: candidate.account_id, briefId: asObject(candidate.account?.metadata).aiSalesBriefId, contactId: contacts[0]?.id, revisionNumber: Number(draft.revision_number ?? 0) }) });
      const payload = await response.json(); if (!response.ok) throw new Error(payload.message ?? "Email regeneration could not be completed.");
      const version = payload.version ?? payload; setComposerDrafts((current) => current.map((item) => item.versionId === draft.versionId ? { ...item, ...version, versionId: version.id ?? item.versionId, approved: false, rejected: false, reviewAction: undefined } : item)); setComposerMessage("New email version ready for your review.");
    } catch (error) { setComposerMessage(error instanceof Error ? error.message : "Email regeneration could not be completed."); }
    finally { setEmailBusyKeys((current) => { const next = new Set(current); next.delete(busyKey); return next; }); }
  }
  async function saveReviewDecision() {
    setReviewBusy(true); setReviewMessage("");
    try {
      const response = await fetch("/api/operator", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: reviewMode, candidateId: candidate.id, sourceQueue: reviewMode === "REOPEN" ? "ARCHIVE" : undefined, reasonCode, otherExplanation, note: reviewNote }) });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.message ?? "The review decision could not be saved.");
      const confirmation = payload.message ?? (reviewMode === "BLOCK" ? "Prospect blocked and moved to History / archive." : "Prospect reopened for review.");
      setReviewMode(null); setReasonCode(""); setOtherExplanation(""); setReviewNote("");
      await onReviewSaved(confirmation);
      setReviewMessage(confirmation);
    } catch (error) { setReviewMessage(error instanceof Error ? error.message : "The review decision could not be saved."); }
    finally { setReviewBusy(false); }
  }
  function reviewSection() {
    const isBlocked = candidate.status === "BLOCKED";
    const otherValid = reasonCode !== "OTHER" || otherExplanation.trim().length >= 3;
    return <section className="drawer-section drawer-review-section"><h3>Reviewer decision</h3>{reviewMessage || reviewNotice ? <p className="drawer-status" role="status">{reviewMessage || reviewNotice}</p> : null}{!isBlocked && !prospectApproved && !reviewMode ? <><p className="drawer-muted">This confirms the prospect is worth pursuing. It does not approve an email or send anything.</p><button type="button" className="operator-button" disabled={reviewBusy} onClick={async () => { setReviewBusy(true); try { const response = await fetch("/api/operator", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "APPROVE_PROSPECT", candidateId: candidate.id }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.message ?? "Prospect approval could not be saved."); await onReviewSaved(payload.message ?? "Prospect approved for drafting."); setReviewMessage(payload.message ?? "Prospect approved for drafting."); } catch (error) { setReviewMessage(error instanceof Error ? error.message : "Prospect approval could not be saved."); } finally { setReviewBusy(false); } }}>Approve prospect for drafting</button></> : null}{prospectApproved && !isBlocked ? <p className="drawer-status" role="status">Prospect approved for drafting. Email approval is still separate.</p> : null}{reviewMode === "BLOCK" ? <div className="drawer-review-form"><label>Why should this prospect leave active review?<select value={reasonCode} onChange={(event) => setReasonCode(event.target.value)}><option value="">Choose a reason</option>{PROSPECT_BLOCK_REASON_OPTIONS.map((reason) => <option key={reason.code} value={reason.code}>{reason.label}</option>)}</select></label>{reasonCode === "OTHER" ? <label>Short explanation<textarea value={otherExplanation} onChange={(event) => setOtherExplanation(event.target.value)} rows={3} required placeholder="Explain the reason briefly" /></label> : null}<label>Reviewer note <span className="drawer-muted">(optional)</span><textarea value={reviewNote} onChange={(event) => setReviewNote(event.target.value)} rows={3} placeholder="Add context for future review" /></label><div className="drawer-actions"><button type="button" className="operator-button danger-button" disabled={reviewBusy || !reasonCode || !otherValid} onClick={() => void saveReviewDecision()}>Save block decision</button><button type="button" className="operator-button secondary" disabled={reviewBusy} onClick={() => setReviewMode(null)}>Cancel</button></div></div> : reviewMode === "REOPEN" ? <div className="drawer-review-form"><p>This will return the prospect to Needs review. It will not be automatically qualified or enriched.</p><div className="drawer-actions"><button type="button" className="operator-button" disabled={reviewBusy} onClick={() => void saveReviewDecision()}>Reopen for review</button><button type="button" className="operator-button secondary" disabled={reviewBusy} onClick={() => setReviewMode(null)}>Cancel</button></div></div> : isBlocked && allowReopen ? <button type="button" className="operator-button" onClick={() => setReviewMode("REOPEN")}>Reopen for review</button> : isBlocked ? <p className="drawer-muted">This prospect is in History / archive and is excluded from active review and outreach actions.</p> : <button type="button" className="operator-button danger-button" onClick={() => setReviewMode("BLOCK")}>Block prospect</button>}</section>;
  }
  function overview() {
    const unresolved = String(resolution.status ?? "UNRESOLVED").toUpperCase() !== "RESOLVED";
    const needs = [...unknowns(candidate), ...(unresolved ? ["Event organiser not confirmed"] : []), ...(!contacts.length ? ["Buyer not identified"] : []), ...(operatorContactState(candidate) === "No email found" ? ["Contact route not found"] : [])];
    return <div className="prospect-tab-content"><section className="drawer-lead"><span className="operator-kicker">WHY THIS PROSPECT?</span><p>{operatorWhyRelevant(candidate)}</p></section><section className="drawer-action-card"><span className="operator-kicker">RECOMMENDED NEXT STEP</span><h3>{operatorNextAction(candidate) === "Confirm organiser" ? "Confirm the event organiser before looking for a buyer." : operatorNextAction(candidate)}</h3><button type="button" className="operator-button" onClick={() => setTab(operatorNextAction(candidate) === "Review email" ? "Email" : "People")}>{operatorNextAction(candidate)}</button></section><section className="drawer-section"><h3>At a glance</h3><dl className="drawer-definition-list"><div><dt>Prospect type</dt><dd>{prospectType(candidate)}</dd></div><div><dt>Event</dt><dd>{String(asObject(candidate.account?.metadata).eventName ?? candidate.candidate_name ?? "Not recorded")}</dd></div><div><dt>Organisation</dt><dd>{organisationName(candidate)}</dd></div><div><dt>Location</dt><dd>{territoryLabel(candidate.territory_code)}</dd></div><div><dt>Website</dt><dd>{candidate.account?.website || candidate.website ? <a href={candidate.account?.website ?? candidate.website ?? "#"} target="_blank" rel="noreferrer">{candidate.account?.website ?? candidate.website}</a> : "Not recorded"}</dd></div><div><dt>Latest activity</dt><dd>{operatorActivityLabel(value.eventFreshness?.state)}</dd></div><div><dt>Identity state</dt><dd>{operatorWorkflowState(candidate)}</dd></div><div><dt>Priority</dt><dd>{prospectPriority(candidate)}</dd></div></dl></section><section className="drawer-section"><h3>What we know</h3>{facts(candidate).length ? facts(candidate).slice(0, 4).map((fact: any, index) => <p className="drawer-fact" key={index}>{fact.claim ?? fact.text}{fact.sourceUrl ? <a href={fact.sourceUrl} target="_blank" rel="noreferrer">{fact.sourceTitle ?? "Source"} ↗</a> : null}</p>) : <p className="drawer-muted">Evidence is still being assembled.</p>}</section><section className="drawer-section"><h3>What needs checking</h3>{needs.length ? <ul className="drawer-list">{needs.slice(0, 5).map((item, index) => <li key={`${item}-${index}`}>{item}</li>)}</ul> : <p className="drawer-muted">No immediate checks are outstanding.</p>}</section><section className="drawer-section"><h3>EventSuite fit</h3>{fit.length ? <div className="fit-summary">{fit.map((item, index) => <div key={index}><strong>{["Event Growth Studio", "Ticketing", "Event Operations"][index]}</strong><span>{String(item.opportunityStrength ?? item.rationale ?? "Assessed").replaceAll("_", " ")}</span></div>)}</div> : <p className="drawer-muted">We have not assessed EventSuite fit yet.</p>}</section>{reviewSection()}</div>;
  }
  function people() {
    return <div className="prospect-tab-content"><section className="drawer-section"><h3>Potential people</h3>{contacts.length ? contacts.map((contact: any, index) => <article className="person-row" key={String(contact.id ?? index)}><div><strong>{String(contact.full_name ?? contact.name ?? "Named contact")}</strong><span>{String(contact.role_title ?? contact.role ?? "Role not recorded")}</span><small>{String(candidate.account?.name ?? organisationName(candidate))}</small></div><div><strong>{operatorRoleLabel(asObject(contact.metadata).buyerRoutingClassification ?? asObject(contact.metadata).personClassification)}</strong><span>{operatorContactState(candidate)}</span><small>{String(asObject(contact.metadata).publicEvidence ?? "Public ownership evidence recorded")}</small></div></article>) : <p className="drawer-empty">No suitable person has been identified yet.</p>}</section><section className="drawer-section"><h3>Selected person</h3><p>{contacts.length ? operatorPersonLabel(candidate) : "No person selected"}</p></section><section className="drawer-section"><h3>Business email</h3><p>{operatorContactState(candidate)}</p><p className="drawer-muted">Human selection remains mandatory before any enrichment.</p></section></div>;
  }
  function email() {
    return <div className="prospect-tab-content"><p className="drawer-muted">Approve the prospect first. Then prepare a draft. Every email is shown in full and approved separately; there is no send, schedule or enrolment action here.</p>{emailLoading ? <Loading label="Loading email drafts for this approved prospect…" /> : null}{(["EMAIL_1", "EMAIL_2", "EMAIL_3"] as const).map((stage, index) => { const draft = drafts.find((item) => item.sequenceStage === stage || item.sequence_stage === stage); const editKey = draft?.versionId ?? draft?.sequenceStage; const approved = Boolean(draft?.approved); return <article className="email-stage" key={stage}><div className="email-stage-heading"><h3>Email {index + 1} — {index === 0 ? "Introduction" : index === 1 ? "Try EventSuite" : "Final note"}</h3><span>{draft ? (approved ? "Email approved" : draft.rejected ? "Not approved" : "Email draft ready for your review") : "No draft yet"}</span></div>{draft ? <>{editingVersionId === editKey ? <><label>Subject<input value={editSubject} onChange={(event) => setEditSubject(event.target.value)} /></label><label>Body<textarea value={editBody} onChange={(event) => setEditBody(event.target.value)} rows={8} /></label></> : <><p><strong>Subject:</strong> {draft.subject ?? "Not recorded"}</p><p><strong>Recipient:</strong> {draft.recipientName ?? contacts[0]?.full_name ?? "No named recipient selected"} · {draft.recipientRole ?? contacts[0]?.role_title ?? "Route to buyer"}</p><pre className="email-body-preview">{draft.renderedBody ?? draft.bodyPlainText ?? draft.body_plain_text ?? "Body not recorded"}</pre></>}<p className="drawer-muted">Links and signature are deterministic and allowlisted. Evidence used: {asArray(draft.personalisationEvidenceIds ?? draft.structured_output?.personalisationEvidenceIds).join(", ") || "Not recorded"}</p><p className="drawer-muted">Claims used: {asArray(draft.claimEvidence ?? draft.structured_output?.claimEvidence).map((item: any) => item.claim ?? item).join(" · ") || "Not recorded"}</p><div className="drawer-actions">{editingVersionId === editKey ? <button type="button" disabled={emailBusyKeys.has(String(editKey))} onClick={() => void saveEdit(draft)}>Save edit for approval</button> : <button type="button" onClick={() => beginEdit(draft)}>Edit</button>}<button type="button" disabled={emailBusyKeys.has(String(editKey))} onClick={() => void regenerateDraft(draft)}>Regenerate</button><button type="button" disabled={emailBusyKeys.has(String(editKey))} onClick={() => void emailReview(draft, "APPROVE")}>Approve email</button><button type="button" disabled={emailBusyKeys.has(String(editKey))} onClick={() => void emailReview(draft, "REJECT", { reasonTags: ["DO_NOT_CONTACT"] })}>Reject</button></div></> : index === 0 ? <><button type="button" className="operator-button" disabled={!canPrepareDraft} onClick={() => void prepareDraft()}>{prospectApproved ? "Prepare email draft" : "Approve prospect first"}</button>{!prospectApproved ? <p className="drawer-muted">“Approve prospect for drafting” is required before an email draft can be requested.</p> : null}</> : <p className="drawer-muted">Prepare and review Email 1 before requesting this follow-up.</p>}</article>; })}<p role="status" className="drawer-status">{composerMessage}</p></div>;
  }
  function history() {
    const events: Array<{ label: string; date?: string | null; note?: string | null }> = [{ label: "Prospect recorded", date: candidate.created_at }, ...facts(candidate).slice(0, 3).map((fact: any) => ({ label: fact.claim ?? "Evidence recorded", date: fact.observedAt ?? candidate.last_seen_at })), ...(contacts.length ? [{ label: "Person evidence available", date: candidate.last_seen_at }] : []), ...(drafts.length ? [{ label: "Draft generated", date: candidate.last_seen_at }] : []), ...(candidate.review_decisions ?? []).map((decision) => ({ label: decision.decision === "BLOCKED" ? `Prospect blocked — ${blockReasonLabel(decision.reason_code)}` : "Prospect reopened for review", date: decision.created_at, note: decision.other_explanation ?? decision.note }))];
    return <div className="prospect-tab-content"><section className="drawer-section"><h3>Review history</h3><ol className="history-timeline">{events.map((item, index) => <li key={index}><strong>{item.label}</strong><span>{formatDate(item.date, "Date not recorded")}</span>{item.note ? <small>{item.note}</small> : null}</li>)}</ol></section><details className="technical-details"><summary>Technical details</summary><p>Source classification, provider outcomes, prompt versions and deterministic codes remain available to authorised review tooling but are not part of the primary operator workflow.</p><p className="mono">Candidate reference: {candidate.id}</p></details></div>;
  }
  return <div className="prospect-drawer-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="prospect-drawer" data-prospect-drawer role="dialog" aria-modal="true" aria-label={`Review ${organisationName(candidate)}`}><header className="prospect-drawer-header"><div><span className="operator-kicker">{prospectType(candidate)}</span><h2>{organisationName(candidate)}</h2><p>{String(asObject(candidate.account?.metadata).eventName ?? candidate.candidate_name ?? "Prospect")}</p></div><div className="drawer-header-actions"><Badge tone={operatorWorkflowState(candidate).toLowerCase().replaceAll(" ", "_")}>{operatorWorkflowState(candidate)}</Badge><button ref={closeRef} type="button" className="inspector-close" onClick={onClose} aria-label="Close prospect drawer">×</button></div></header>{loading ? <Loading label="Loading evidence and review history…" /> : <><div className="drawer-progress" aria-label="Review progress"><span className="active">Prospect</span><span>Person</span><span>Email</span><span>Approval</span></div><nav className="drawer-tabs" role="tablist" aria-label="Prospect review tabs">{(["Overview", "People", "Email", "History"] as const).map((item) => <button type="button" role="tab" className={tab === item ? "active" : undefined} aria-selected={tab === item} onClick={() => setTab(item)} key={item}>{item}</button>)}</nav>{tab === "Overview" ? overview() : tab === "People" ? people() : tab === "Email" ? email() : history()}</>}</aside></div>;
}

export function ProspectsView() {
  const [queue, setQueue] = useState("NEEDS_REVIEW"); const [query, setQuery] = useState(""); const [territory, setTerritory] = useState("ALL"); const [prospectTypeFilter, setProspectTypeFilter] = useState("ALL"); const [reviewState, setReviewState] = useState("ALL"); const [contactFilter, setContactFilter] = useState("ALL"); const [emailFilter, setEmailFilter] = useState("ALL"); const [priority, setPriority] = useState("ALL"); const [showFilters, setShowFilters] = useState(false); const [sort, setSort] = useState("attention"); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(25); const [cursor, setCursor] = useState<string | null>(null); const [cursorDirection, setCursorDirection] = useState<"next" | "previous">("next"); const [selectedId, setSelectedId] = useState<string | null>(null); const [restoreFocus, setRestoreFocus] = useState<HTMLElement | null>(null); const [reviewNotices, setReviewNotices] = useState<Record<string, string>>({}); const [detailCache, setDetailCache] = useState<Record<string, OperatorCandidate>>({}); const [detailLoading, setDetailLoading] = useState(false); const [localStatuses, setLocalStatuses] = useState<Record<string, string>>({});
  const resetPagination = useCallback(() => { setPage(1); setCursor(null); setCursorDirection("next"); }, []);
  const queueQuery = useMemo(() => { const params = new URLSearchParams({ view: "prospects", queue, search: query, territory, prospectType: prospectTypeFilter, reviewState, contactState: contactFilter, emailState: emailFilter, priority, sort, page: String(page), pageSize: String(pageSize), direction: cursorDirection }); if (cursor) params.set("cursor", cursor); return params.toString(); }, [contactFilter, cursor, cursorDirection, emailFilter, page, pageSize, priority, prospectTypeFilter, query, queue, reviewState, sort, territory]);
  const { data: rawData, state } = useOperatorData(queueQuery); const data = rawData as OperatorPayload & { total?: number; page?: number; pageSize?: number; pageCount?: number; queueCounts?: Record<string, number>; hasNext?: boolean; hasPrevious?: boolean; nextCursor?: string | null; previousCursor?: string | null; returned?: number };
  const detailLoadingIds = useRef(new Set<string>());
  const loadDetail = useCallback((id: string) => { if (detailCache[id] || detailLoadingIds.current.has(id)) return; detailLoadingIds.current.add(id); setDetailLoading(true); void fetch(`/api/operator?view=prospect-detail&candidateId=${encodeURIComponent(id)}`).then(async (response) => { if (!response.ok) throw new Error("Prospect detail could not be loaded."); return response.json(); }).then((payload) => { const detail = payload.candidates?.[0]; if (detail) setDetailCache((current) => ({ ...current, [id]: detail })); }).catch(() => setReviewNotices((current) => ({ ...current, [id]: "Prospect detail could not be loaded." }))).finally(() => { detailLoadingIds.current.delete(id); setDetailLoading(false); }); }, [detailCache]);
  useEffect(() => { const sync = () => setSelectedId(new URL(window.location.href).searchParams.get("prospect")); sync(); window.addEventListener("popstate", sync); return () => window.removeEventListener("popstate", sync); }, []);
  useEffect(() => { if (selectedId) loadDetail(selectedId); }, [loadDetail, selectedId]);
  const openDrawer = (id: string, trigger: HTMLElement) => { const url = new URL(window.location.href); url.searchParams.set("prospect", id); window.history.pushState({ prospect: id }, "", url); setRestoreFocus(trigger); setSelectedId(id); loadDetail(id); };
  const closeDrawer = () => { const url = new URL(window.location.href); url.searchParams.delete("prospect"); window.history.replaceState({}, "", url); setSelectedId(null); };
  const listCandidates = useMemo(() => data.candidates.map((candidate) => localStatuses[candidate.id] ? { ...candidate, status: localStatuses[candidate.id] } : candidate), [data.candidates, localStatuses]);
  if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const labels: Record<string, string> = { NEEDS_REVIEW: "Needs review", READY_PEOPLE: "Ready for people", DRAFTS: "Drafts to review", APPROVED: "Approved drafts", DEFERRED: "Deferred", ARCHIVE: "History / archive", ALL: "All" };
  const counts = Object.fromEntries(Object.entries(labels).map(([key, label]) => [key, { label, count: data.queueCounts?.[key] ?? data.candidates.length }]));
  const fallbackArchive = (candidate: OperatorCandidate) => ["REJECTED", "BLOCKED", "DUPLICATE"].includes(candidate.status) || Boolean(candidate.dedupe_of_candidate_id);
  const fallbackState = (candidate: OperatorCandidate) => operatorWorkflowState(candidate);
  const visible = typeof data.total === "number" ? listCandidates : listCandidates.filter((candidate) => queue === "ALL" || queue === "ARCHIVE" ? (queue === "ARCHIVE" ? fallbackArchive(candidate) : true) : !fallbackArchive(candidate) && (queue === "NEEDS_REVIEW" ? ["Needs identity review", "Contact needs review", "Draft awaiting approval"].includes(fallbackState(candidate)) : queue === "READY_PEOPLE" ? fallbackState(candidate) === "Ready for person review" : queue === "DRAFTS" ? fallbackState(candidate) === "Draft awaiting approval" : queue === "APPROVED" ? fallbackState(candidate) === "Draft approved — not sent" : queue === "DEFERRED" ? fallbackState(candidate) === "Deferred" : true)); const selectedListCandidate = visible.find((candidate) => candidate.id === selectedId) ?? data.candidates.find((candidate) => candidate.id === selectedId) ?? null; const selected = selectedId ? detailCache[selectedId] ?? selectedListCandidate : null;
  const reset = () => { setQueue("NEEDS_REVIEW"); setQuery(""); setTerritory("ALL"); setProspectTypeFilter("ALL"); setReviewState("ALL"); setContactFilter("ALL"); setEmailFilter("ALL"); setPriority("ALL"); resetPagination(); };
  const goNext = () => { if (data.hasNext && data.nextCursor) { setCursor(data.nextCursor); setCursorDirection("next"); setPage((current) => current + 1); } };
  const goPrevious = () => { if (data.hasPrevious && data.previousCursor) { setCursor(data.previousCursor); setCursorDirection("previous"); setPage((current) => Math.max(1, current - 1)); } };
  return <>
    <PageHeader compact eyebrow="PROSPECTS" title="Prospects" lede="Review potential EventSuite customers and decide what happens next." />
    <div className="prospect-queue-tabs" role="tablist" aria-label="Prospect queues">
      {Object.entries(counts).map(([key, item]) => <button key={key} type="button" role="tab" aria-selected={queue === key} className={queue === key ? "active" : undefined} onClick={() => { if (queue !== key) { setQueue(key); resetPagination(); } }}>{item.label}<span>{item.count}</span></button>)}
    </div>
    <div className="prospect-toolbar">
      <label className="prospect-search">Search<input value={query} onChange={(event) => { setQuery(event.target.value); resetPagination(); }} placeholder="Search prospects" /></label>
      <button type="button" className={showFilters ? "filter-toggle active" : "filter-toggle"} onClick={() => setShowFilters(!showFilters)} aria-expanded={showFilters}>Filters</button>
      <label className="sort-control">Sort<select value={sort} onChange={(event) => { if (event.target.value !== sort) { setSort(event.target.value); resetPagination(); } }}><option value="attention">Needs attention first</option><option value="recent">Most recent</option><option value="name">Prospect name</option><option value="ready">Ready for review</option></select></label>
    </div>
    {showFilters ? <div className="prospect-filter-panel">
      <label>Prospect type<select value={prospectTypeFilter} onChange={(event) => { setProspectTypeFilter(event.target.value); resetPagination(); }}><option value="ALL">All types</option><option value="Event">Event</option><option value="Organisation">Organisation</option><option value="Person">Person</option><option value="Venue">Venue</option></select></label>
      <label>Territory<select value={territory} onChange={(event) => { setTerritory(event.target.value); resetPagination(); }}><option value="ALL">All territories</option><option value="ZA">South Africa</option><option value="GB">United Kingdom</option></select></label>
      <label>Review state<select value={reviewState} onChange={(event) => { setReviewState(event.target.value); resetPagination(); }}><option value="ALL">All states</option><option value="Needs identity review">Needs identity review</option><option value="Ready for person review">Ready for person review</option><option value="Contact needs review">Contact needs review</option></select></label>
      <label>Contact state<select value={contactFilter} onChange={(event) => { setContactFilter(event.target.value); resetPagination(); }}><option value="ALL">All people</option><option value="PERSON">Person identified</option><option value="NONE">No person selected</option></select></label>
      <label>Email state<select value={emailFilter} onChange={(event) => { setEmailFilter(event.target.value); resetPagination(); }}><option value="ALL">All email states</option><option value="VERIFIED">Business email verified</option><option value="REVIEW">Needs review / not found</option></select></label>
      <label>Priority<select value={priority} onChange={(event) => { setPriority(event.target.value); resetPagination(); }}><option value="ALL">All priorities</option><option value="Phase One priority">Phase One priority</option><option value="Standard priority">Standard priority</option><option value="Deferred">Deferred</option></select></label>
      <button type="button" className="clear-filter-button" onClick={reset}>Clear filters</button>
    </div> : null}
    <div className="prospect-filter-chips">{queue !== "NEEDS_REVIEW" ? <span>{counts[queue as keyof typeof counts]?.label}</span> : null}{territory !== "ALL" ? <span>{territoryLabel(territory)}</span> : null}{prospectTypeFilter !== "ALL" ? <span>{prospectTypeFilter}</span> : null}{query ? <span>Search: {query}</span> : null}</div>
    <div className="collection-toolbar prospect-count"><span><strong>{data.total ?? visible.length} prospects</strong>{queue === "ALL" ? " shown" : ""}</span><span>{visible.length ? "Select a row to review the prospect." : "No prospects need action in this view."}</span></div>
    {visible.length ? <CollectionTable label="Prospects" count={data.total ?? visible.length}><thead><tr><th>Prospect</th><th>Type</th><th>Why relevant</th><th>Person and email</th><th>Status</th><th>Next action</th></tr></thead><tbody>{visible.map((candidate) => <ProspectQueueRow key={candidate.id} candidate={candidate} selected={candidate.id === selectedId} onOpen={openDrawer} />)}</tbody></CollectionTable> : <EmptyState title="No prospects in this queue" text="Try another queue or adjust the filters. No records were changed." />}
    <Pagination page={data.page ?? page} pageSize={data.pageSize ?? pageSize} total={data.total ?? visible.length} pageCount={data.pageCount} hasNext={data.hasNext} hasPrevious={data.hasPrevious} onNext={goNext} onPrevious={goPrevious} onPageSize={(size) => { if (size !== pageSize) { setPageSize(size); resetPagination(); } }} />
    {selected ? <ProspectDrawer candidate={selected} loading={detailLoading && !detailCache[selected.id]} onClose={closeDrawer} restoreFocus={restoreFocus} reviewNotice={reviewNotices[selected.id]} onReviewSaved={async (message) => { setReviewNotices((current) => ({ ...current, [selected.id]: message })); if (message.includes("blocked")) setLocalStatuses((current) => ({ ...current, [selected.id]: "BLOCKED" })); if (message.includes("reopened")) setLocalStatuses((current) => ({ ...current, [selected.id]: "REVIEW_REQUIRED" })); setDetailCache((current) => ({ ...current, [selected.id]: { ...selected, status: message.includes("blocked") ? "BLOCKED" : message.includes("reopened") ? "REVIEW_REQUIRED" : selected.status, prospect_approval: message.includes("approved") ? { decision: "APPROVED" } : selected.prospect_approval } })); }} allowReopen={queue === "ARCHIVE" && ["REJECTED", "BLOCKED", "DUPLICATE"].includes(selected.status)} /> : null}
  </>;
}
const siteTypeLabelsForFilter = { ORGANISATION_OFFICIAL: true, EVENT_OFFICIAL: true, TICKETING_PROVIDER: true, EVENT_LISTING_DIRECTORY: true, VENUE_OFFICIAL: true, VENUE_CALENDAR: true, SOCIAL_COMMUNITY: true, NEWS_EDITORIAL: true, UNKNOWN: true };
const statusLabelsForFilter = { REVIEW_REQUIRED: true, QUALIFIED: true, REJECTED: true, BLOCKED: true, DUPLICATE: true, DISCOVERED: true, RESOLVED: true };

function EvidenceList({ label, items, kind }: { label: string; items: Array<Record<string, any>>; kind: "FACT" | "INFERENCE" | "UNKNOWN" }) { return <section className={`evidence-block ${kind.toLowerCase()}`}><div className="section-heading"><span className="operator-kicker">{label}</span><Badge tone={kind.toLowerCase()}>{kind}</Badge></div>{items.length ? items.map((item, index) => <article className="evidence-item" key={`${kind}-${index}`}><p>{typeof item === "string" ? item : item.claim ?? item.text ?? "Evidence detail not recorded"}</p>{typeof item === "object" && item.sourceUrl ? <a href={item.sourceUrl} target="_blank" rel="noreferrer">{item.sourceTitle ?? "Open source"} ↗</a> : null}<span>{typeof item === "object" ? item.confidence ?? "Confidence not recorded" : "Important unanswered question"}</span></article>) : <p className="muted">None recorded.</p>}</section>; }

function Lens({ label, value }: { label: string; value: any }) { const item = asObject(value); return <article className="lens-card"><div className="lens-title"><span className="operator-kicker">{label}</span><Badge tone="neutral">{String(item.opportunityStrength ?? item.status ?? "UNKNOWN").replaceAll("_", " ")}</Badge></div><p>{String(item.rationale ?? item.summary ?? "No conclusion recorded for this lens.")}</p><div className="lens-evidence"><strong>FACTS</strong><span>{asArray(item.facts ?? item.evidence).slice(0, 3).map((entry: any) => typeof entry === "string" ? entry : entry.claim).join(" · ") || "None recorded"}</span></div></article>; }

function Contactability({ candidate }: { candidate: OperatorCandidate }) { const contacts = candidate.contacts ?? []; const research = asObject(candidate.contact_research); return <section className="contact-section"><div className="section-heading"><span className="operator-kicker">CONTACTABILITY</span><Badge tone={contacts.length ? "verified" : "neutral"}>{contactState(candidate)}</Badge></div>{contacts.length ? contacts.map((contact, index) => { const metadata = asObject(contact.metadata); return <article className="contact-card" key={String(contact.id ?? index)}><strong>{String(contact.email ?? contact.phone ?? contact.full_name ?? contact.name ?? "Public route")}</strong><dl><div><dt>OWNER</dt><dd>{String(candidate.account?.name ?? "Resolved target not recorded")}</dd></div><div><dt>SOURCE</dt><dd>{String(metadata.sourceTitle ?? metadata.sourceUrl ?? "Source not recorded")}</dd></div><div><dt>WHY WE BELIEVE IT BELONGS</dt><dd>{String(metadata.publicEvidence ?? "Ownership evidence not recorded")}</dd></div></dl><Badge tone="verified">{String(contact.verification_status ?? "VERIFIED")}</Badge></article>; }) : <div className="contact-empty"><strong>NO VERIFIED TARGET CONTACT</strong><p>{research.status === "CONTACT_RESEARCH_REQUIRED" ? "Contact research is required before a route can be presented as usable." : "No persisted contact evidence establishes a usable route for the resolved target."}</p></div>}</section>; }

export function ProspectDetailView({ candidateId }: { candidateId: string }) {
  const { data, state } = useOperatorData(`view=prospect&candidateId=${encodeURIComponent(candidateId)}`); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />;
  const candidate = data.candidates[0]; if (!candidate) return <EmptyState title="Prospect not found" text="This record may not be available to the current member." />;
  const value = intelligence(candidate); const resolution = asObject(value.organisationResolution); const target = candidate.organiser_name || candidate.account?.name; const source = sourceType(candidate);
  return <><PageHeader eyebrow="PROSPECT DETAIL" title={target ?? "ORGANISATION NOT YET RESOLVED"} lede="Follow the evidence story from discovery signal to commercial target, then inspect contactability and the recommended next action." action={<Link className="operator-button secondary" href="/operator/prospects">Back to prospects</Link>} /><div className="origin-strip"><span className="operator-label">FOUND IN RUN</span><strong>{formatDate(candidate.created_at)} · {territoryLabel(candidate.territory_code)} · {lensLabel(asObject(data.runs.find((run) => run.id === candidate.discovery_run_id)).focus)} · {shortId(candidate.discovery_run_id)}</strong><Badge tone={contextLabel(candidate, data.latestRunId).toLowerCase()}>{contextLabel(candidate, data.latestRunId)}</Badge></div><section className="target-header"><div><span className="operator-kicker">RESOLVED COMMERCIAL TARGET</span><h2>{target ?? "ORGANISATION NOT YET RESOLVED"}</h2><p>{candidate.account?.website ? <a href={candidate.account.website} target="_blank" rel="noreferrer">{candidate.account.website} ↗</a> : "Authoritative organisation website not recorded"}</p></div><dl><div><dt>RESOLUTION</dt><dd>{String(resolution.status ?? "UNRESOLVED")}</dd></div><div><dt>CONFIDENCE</dt><dd>{String(resolution.confidence ?? "Not recorded")}</dd></div><div><dt>OPPORTUNITY</dt><dd>{primaryOpportunity(candidate)}</dd></div><div><dt>STATUS</dt><dd><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></dd></div></dl></section><div className="story-grid"><section className="story-section"><div className="story-heading"><span className="operator-kicker">WHAT WE FOUND</span><Badge tone="neutral">{siteTypeLabel(source)}</Badge></div><h2>{candidate.candidate_name}</h2><p>Origin: {candidate.origin.replaceAll("_", " ")} · Source: {siteTypeLabel(source)}</p>{candidate.website ? <a href={candidate.website} target="_blank" rel="noreferrer">Open discovery source ↗</a> : <p className="muted">Discovery URL not recorded.</p>}<p>{String(value.eventConnection?.reasons?.[0] ?? "Discovery signal context is recorded in the evidence below.")}</p></section><section className="story-section"><div className="story-heading"><span className="operator-kicker">WHO WE THINK THE CUSTOMER IS</span><Badge tone={resolution.status === "RESOLVED" ? "verified" : "neutral"}>{resolution.status === "RESOLVED" ? "Resolved" : "Unresolved"}</Badge></div><p>{String(resolution.evidence?.[0]?.claim ?? "The persisted evidence does not establish organiser responsibility yet.")}</p>{resolution.officialWebsite ? <a href={resolution.officialWebsite} target="_blank" rel="noreferrer">Open official organisation site ↗</a> : null}</section></div><section className="identity-section"><div className="section-heading"><span className="operator-kicker">IDENTITY / ORGANISER EVIDENCE</span></div><EvidenceList label="Organiser evidence" items={asArray(resolution.evidence)} kind="FACT" /></section><section className="event-context"><div className="section-heading"><span className="operator-kicker">EVENT / ACTIVITY CONTEXT</span></div><div className="context-columns"><div><span className="operator-label">FRESHNESS</span><strong>{String(value.eventFreshness?.state ?? "Not recorded")}</strong></div><div><span className="operator-label">RELATIONSHIP</span><strong>{candidate.relationship}</strong></div><div><span className="operator-label">ALIASES</span><strong>{asArray(resolution.aliases).join(" · ") || "None recorded"}</strong></div></div></section><section className="commercial-section"><div className="section-heading"><span className="operator-kicker">COMMERCIAL INTELLIGENCE</span><span className="muted">EventSuite hypotheses remain separate</span></div><div className="lens-grid"><Lens label="EVENT GROWTH" value={value.egs} /><Lens label="TICKETING" value={value.ticketing} /><Lens label="EVENT OPERATIONS" value={value.ecc} /></div><div className="evidence-grid"><EvidenceList label="FACTS" items={facts(candidate)} kind="FACT" /><EvidenceList label="INFERENCES" items={inferences(candidate)} kind="INFERENCE" /><EvidenceList label="UNKNOWNS" items={unknowns(candidate).map((item) => ({ text: item }))} kind="UNKNOWN" /></div></section><section className="buyer-section"><div className="section-heading"><span className="operator-kicker">BUYER / PROBLEM OWNER</span></div><h2>{asArray(value.buyerProblemOwner?.likelyRoles).join(" · ") || "Role not established"}</h2><p>{String(value.buyerProblemOwner?.rationale ?? "A named person is not shown without public evidence.")}</p></section><Contactability candidate={candidate} /><section className="recommendation"><span className="operator-kicker">AI RECOMMENDATION</span><h2>{String(value.recommendedNextAction ?? "No recommendation recorded")}</h2><p>{String(value.outreachBlockOrReviewReason ?? value.nextBestCommercialAction?.rationale ?? "No additional rationale recorded.")}</p><Badge tone={needsReview(candidate) ? "review_required" : "neutral"}>{needsReview(candidate) ? "Needs your decision" : "No human action required"}</Badge></section><details className="diagnostics"><summary>Diagnostics (collapsed)</summary><p>Candidate ID: <span className="mono">{candidate.id}</span></p><p>Origin run: <span className="mono">{candidate.discovery_run_id}</span></p><p>Raw JSON is intentionally not required for normal operator understanding.</p></details></>;
}

export function ReviewView() { const { data, state } = useOperatorData("view=review"); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />; const items = data.candidates.filter(needsReview); return <><PageHeader eyebrow="NEEDS YOUR DECISION" title="A decision queue, not a failure bucket" lede="The first column states the specific human decision. Generic ‘needs more research’ items stay out of this queue." />{items.length ? <CollectionTable label="Needs Review" count={items.length}><thead><tr><th>DECISION REQUIRED</th><th>ORGANISATION</th><th>DISCOVERY SIGNAL</th><th>WHY BLOCKED</th><th>OPPORTUNITY</th><th>CONTACT</th><th>FOUND / AGE</th><th>RUN</th><th>ACTION</th></tr></thead><tbody>{items.map((candidate) => <CandidateRow key={candidate.id} candidate={candidate} latestRunId={data.latestRunId} review />)}</tbody></CollectionTable> : <EmptyState title="No decision-oriented items" text="The AI Sales Team has no specific human decision to request right now." />}</> }

export function HistoricalView() { const { data, state } = useOperatorData("view=historical"); if (state === "loading") return <Loading />; if (state === "error") return <ErrorState />; const items = data.candidates.filter((candidate) => ["HISTORICAL", "CALIBRATION", "LEGACY"].includes(contextLabel(candidate, data.latestRunId))); return <><PageHeader eyebrow="HISTORICAL / CALIBRATION" title="Inspect old evidence safely" lede="A dense, searchable collection for older results. Replay remains deferred and historical context is never presented as current sales work." /><div className="future-compare"><span className="operator-kicker">FUTURE COMPARISON SPACE</span><strong>ORIGINAL HISTORICAL RESULT <span>vs</span> CURRENT REPLAY RESULT</strong><p>Replay is deliberately not implemented in V1.</p></div>{items.length ? <CollectionTable label="Historical and calibration records" count={items.length}><thead><tr><th>CONTEXT</th><th>DATE / RUN</th><th>ORGANISATION OR SIGNAL</th><th>TERRITORY</th><th>SOURCE</th><th>ORIGINAL STATUS</th><th>CURRENT INTERPRETATION</th><th>EVALUATION CONTEXT</th><th>ACTION</th></tr></thead><tbody>{items.map((candidate) => <tr key={candidate.id}><td><Badge tone={contextLabel(candidate, data.latestRunId).toLowerCase()}>{contextLabel(candidate, data.latestRunId)}</Badge></td><td><span>{formatDate(candidate.created_at)}</span><small>{shortId(candidate.discovery_run_id)}</small></td><td><strong>{organisationName(candidate)}</strong><span>{discoverySignal(candidate)}</span></td><td>{territoryLabel(candidate.territory_code)}</td><td>{siteTypeLabel(sourceType(candidate))}</td><td><Badge tone={candidate.status.toLowerCase()}>{statusLabel(candidate.status)}</Badge></td><td>{candidate.status === "QUALIFIED" ? "Previously qualified; inspect current evidence" : "Historical evidence only"}</td><td>{contextLabel(candidate, data.latestRunId) === "CALIBRATION" ? "Calibration context retained" : "No replay evaluation"}</td><td><CandidateLink candidate={candidate} /></td></tr>)}</tbody></CollectionTable> : <EmptyState title="No historical records in the current data window" text="Records are labelled conservatively; calibration or legacy context is not fabricated when it is not persisted." />}</> }
